<script setup lang="ts">
import { computed, onBeforeUnmount, onMounted, ref, watch } from 'vue'
import { storeToRefs } from 'pinia'
import { api, APIError } from '../api'
import { formatDate, formatNumber, locale, t } from '../i18n'
import { useWorkspaceStore } from '../stores/workspace'
import { Button } from '../components/ui/button'
import { ScrollArea } from '../components/ui/scroll-area'
import Icon from '../components/Icon.vue'
import DatePicker from '../components/DatePicker.vue'
import AppSelect from '../components/AppSelect.vue'
import WorkloadTrends from '../components/WorkloadTrends.vue'
import WorkloadIterations from '../components/WorkloadIterations.vue'
import { currentWorkloadMonth, moveWorkloadMonth, validWorkloadMonth, workloadRoleNames, workloadRows, type PersonalWorkloadReport, type TeamWorkloadReport, type WorkloadDimension, type WorkloadMetrics, type WorkloadPerson, type WorkloadReport, type WorkloadSort } from '../workload'

const workspace=useWorkspaceStore(),{identityConflict}=storeToRefs(workspace)
const trendRefresh=ref(0),monthValid=ref(true)
const month=ref(currentWorkloadMonth()),report=ref<WorkloadReport|null>(null),personalReport=ref<PersonalWorkloadReport|null>(null),teamReport=ref<TeamWorkloadReport|null>(null),loading=ref(false),teamLoading=ref(false),error=ref(''),personalError=ref(''),teamError=ref(''),forbidden=ref(false),dimension=ref<WorkloadDimension>('people'),search=ref(''),department=ref('*'),role=ref(''),sort=ref<WorkloadSort>('weight'),descending=ref(true)
let sequence=0,disposed=false,controller:AbortController|undefined
const rows=computed(()=>report.value?workloadRows(report.value,dimension.value,{search:search.value,department:department.value,role:role.value,sort:sort.value,descending:descending.value,locale:locale.value,translate:t}):[])
const dimensions: {key:WorkloadDimension;name:string}[]=[{key:'people',name:'人员贡献'},{key:'departments',name:'部门汇总'},{key:'roles',name:'职能汇总'}]
const metrics: {key:Exclude<WorkloadSort,'name'>;name:string}[]=[{key:'weight',name:'已填工作权重'},{key:'requirementCount',name:'关联需求'},{key:'shippedRequirementCount',name:'已上线需求'},{key:'defectCount',name:'迭代缺陷'}]
const hasGaps=computed(()=>!!report.value&&(report.value.unassignedWeight>0||report.value.unassignedRequirementCount>0||report.value.unassignedDefectCount>0||report.value.unestimatedRequirementCount>0||report.value.ambiguousSprintItemCount>0))
const departmentOptions=computed(()=>[
  {value:'*',label:t('所有部门')},
  ...(report.value?.departments||[]).map(item=>({value:item.id,label:item.name||t('未分配部门')})),
])
const roleOptions=computed(()=>[
  {value:'',label:t('所有职能')},
  ...(report.value?.roles||[]).map(item=>({value:item.key,label:t(workloadRoleNames[item.key]||item.key)})),
])
const formatWeight=(value:number)=>formatNumber(value,{maximumFractionDigits:6})
const personalCards=computed(()=>personalReport.value?[{key:'weight',name:'已填工作权重',value:formatWeight(personalReport.value.person.weight),hint:'职能权重相加，不是工时'},{key:'requirementCount',name:'关联需求',value:formatNumber(personalReport.value.person.requirementCount),hint:'仅统计当前有权访问项目的工作项'},{key:'shippedRequirementCount',name:'已上线需求',value:formatNumber(personalReport.value.person.shippedRequirementCount),hint:'已完成类别且属于工作流结束状态'},{key:'defectCount',name:'迭代缺陷',value:formatNumber(personalReport.value.person.defectCount),hint:'按稳定处理人 ID 归属'}]:[])
function validMetrics(value:unknown):value is WorkloadMetrics{return !!value&&typeof value==='object'&&['weight','requirementCount','shippedRequirementCount','defectCount','estimatedRoleCount','unestimatedRoleCount'].every(key=>typeof (value as Record<string,unknown>)[key]==='number'&&Number.isFinite((value as Record<string,number>)[key])&&(value as Record<string,number>)[key]>=0)}
function validPerson(value:unknown):value is WorkloadPerson{return !!value&&typeof value==='object'&&typeof (value as Record<string,unknown>).userId==='string'&&typeof (value as Record<string,unknown>).name==='string'&&validMetrics(value)}
function validPersonal(data:unknown,tenant:string|undefined,user:string,selectedMonth:string):data is PersonalWorkloadReport{const item=data as PersonalWorkloadReport;return !!item&&item.month===selectedMonth&&item.scope?.type==='personal'&&item.scope.tenantId===tenant&&validPerson(item.person)&&item.person.userId===user&&!!item.team&&typeof item.team.available==='boolean'}
function validTeam(data:unknown,tenant:string|undefined,selectedMonth:string):data is TeamWorkloadReport{const item=data as TeamWorkloadReport;return !!item&&item.month===selectedMonth&&item.scope?.type==='team'&&item.scope.tenantId===tenant&&Array.isArray(item.people)&&item.people.every(validPerson)}
function invalidate(){sequence++;controller?.abort();report.value=null;personalReport.value=null;teamReport.value=null;loading.value=false;teamLoading.value=false;error.value='';personalError.value='';teamError.value='';forbidden.value=false}
function setMonthValidity(valid:boolean){monthValid.value=valid;if(!valid){sequence++;controller?.abort();loading.value=false;teamLoading.value=false}}
async function load(){
  if(disposed||identityConflict.value||!workspace.currentUser||!monthValid.value)return
  const request=++sequence,selectedMonth=month.value,user=workspace.currentUser.id,tenant=workspace.session?.tenant.id
  controller?.abort();controller=new AbortController();error.value='';personalError.value='';teamError.value='';forbidden.value=false
  if(report.value?.month!==selectedMonth)report.value=null
  if(personalReport.value?.month!==selectedMonth)personalReport.value=null
  if(teamReport.value?.month!==selectedMonth)teamReport.value=null
  if(!validWorkloadMonth(selectedMonth)){loading.value=false;error.value='月份必须为有效的 YYYY-MM 格式';return}
  loading.value=true
  const current=()=>!disposed&&request===sequence&&!identityConflict.value&&workspace.currentUser?.id===user&&workspace.session?.tenant.id===tenant&&month.value===selectedMonth
  try{
    const personal=await api<PersonalWorkloadReport>('/reports/workload/personal?month='+encodeURIComponent(selectedMonth),{signal:controller.signal})
    if(!current())return
    if(!validPersonal(personal,tenant,user,selectedMonth))throw new Error('个人工作量统计上下文校验失败，请重试')
    personalReport.value=personal
  }catch(cause){if(current()){personalReport.value=null;personalError.value=cause instanceof Error?cause.message:t('我的工作量暂时无法读取，请稍后重试')}}
  if(current()&&personalReport.value?.team.available){
    teamLoading.value=true
    try{const team=await api<TeamWorkloadReport>('/reports/workload/team?month='+encodeURIComponent(selectedMonth),{signal:controller.signal});if(!current())return;if(!validTeam(team,tenant,selectedMonth))throw new Error('组员工作量统计上下文校验失败，请重试');teamReport.value=team}
    catch(cause){if(current()){teamReport.value=null;teamError.value=cause instanceof Error?cause.message:t('组员工作量暂时无法读取，请稍后重试')}}
    finally{if(current())teamLoading.value=false}
  }else if(current())teamReport.value=null
  if(current()&&workspace.canViewReports){
    try{const data=await api<WorkloadReport>('/reports/workload?month='+encodeURIComponent(selectedMonth),{signal:controller.signal});if(!current())return;if(data.month!==selectedMonth||data.scope.tenantId!==tenant||data.scope.type!=='organization')throw new Error('统计上下文校验失败，请重试');report.value=data;trendRefresh.value++}
    catch(cause){if(current()){forbidden.value=cause instanceof APIError&&[401,403].includes(cause.status);if(forbidden.value)report.value=null;else error.value=cause instanceof Error?cause.message:t('月度工作量暂时无法读取，请稍后重试')}}
  }else if(current())report.value=null
  if(current())loading.value=false
}
function changeSort(key:WorkloadSort){if(sort.value===key)descending.value=!descending.value;else{sort.value=key;descending.value=key!=='name'}}
function resetFilters(){search.value='';department.value='*';role.value=''}
function selectDepartment(value:string|number){department.value=String(value)}
function selectRole(value:string|number){role.value=String(value)}
watch(month,()=>{resetFilters();void load()})
watch(dimension,resetFilters)
watch(()=>[workspace.currentUser?.id,workspace.session?.tenant.id,identityConflict.value],()=>{invalidate();if(!identityConflict.value&&workspace.currentUser)void load()})
onMounted(()=>{void load();window.addEventListener('devflow-identity-changed',invalidate);window.addEventListener('devflow-auth-expired',invalidate)})
onBeforeUnmount(()=>{disposed=true;invalidate();window.removeEventListener('devflow-identity-changed',invalidate);window.removeEventListener('devflow-auth-expired',invalidate)})
</script>

<template>
  <div class="workload-page">
    <header class="workload-heading compact-page-heading"><div><h1>{{t('工作量统计')}}</h1><details class="page-heading-note"><summary :aria-label="t('页面说明')" :title="t('页面说明')"><span aria-hidden="true">?</span></summary><p>{{t('优先查看个人工作量；企业范围统计仅向获得专门授权的成员展示。')}}</p></details></div><Button variant="outline" :disabled="loading||identityConflict||!monthValid" @click="load"><Icon name="refresh" :size="15"/>{{t('刷新统计')}}</Button></header>
    <section class="workload-month"><div><span class="workload-month-icon" aria-hidden="true">▦</span><div><b>{{t('迭代归属月份')}}</b><small>{{t('按迭代结束日期归月，不按需求创建时间')}}</small></div></div><div class="workload-month-controls"><Button variant="ghost" size="icon-sm" :aria-label="t('上个月')" :disabled="identityConflict||moveWorkloadMonth(month,-1)===month" @click="month=moveWorkloadMonth(month,-1)">‹</Button><DatePicker v-model="month" mode="month" required @validity-change="setMonthValidity" min="0001-01" max="9998-12" :label="t('选择统计月份')" :disabled="identityConflict"/><Button variant="ghost" size="icon-sm" :aria-label="t('下个月')" :disabled="identityConflict||moveWorkloadMonth(month,1)===month" @click="month=moveWorkloadMonth(month,1)">›</Button><Button variant="outline" size="sm" :disabled="identityConflict||month===currentWorkloadMonth()" @click="month=currentWorkloadMonth()">{{t('本月')}}</Button></div></section>
    <p v-if="personalError" class="workload-error" role="alert">{{t(personalError)}}</p>
    <div v-else-if="loading&&!personalReport" class="workload-empty" role="status"><span class="spinner"></span>{{t('正在计算我的工作量…')}}</div>
    <section v-if="personalReport" class="workload-personal" :aria-label="t('我的工作量统计')">
      <header class="workload-personal-heading"><div><span class="workload-eyebrow">{{t('个人视图')}}</span><h2>{{t('我的工作量统计')}}</h2><p>{{t('仅统计当前账号有权访问项目中归属于我的需求职能与缺陷。')}}</p></div><div class="workload-personal-owner"><span class="workload-avatar">{{personalReport.person.name.slice(0,1)}}</span><div><b>{{personalReport.person.name}}</b><small>{{t('{count} 个可访问项目',{count:personalReport.scope.projectCount})}} · {{t('{count} 个迭代',{count:personalReport.sprintCount})}}</small></div></div></header>
      <div class="workload-scope workload-personal-scope"><span><i></i>{{t('当前状态快照')}} · {{formatDate(personalReport.generatedAt)}}</span><small>{{t('按迭代结束日期归月，不按需求创建时间')}}</small></div>
      <div class="workload-cards workload-personal-cards"><article v-for="metric in personalCards" :key="metric.key"><span>{{t(metric.name)}}</span><b>{{metric.value}}</b><small>{{t(metric.hint)}}</small></article></div>
    </section>
    <WorkloadIterations v-if="personalReport" :month="month" :refresh-key="trendRefresh" :disabled="identityConflict||!monthValid"/>
    <section v-if="personalReport?.team.available" class="workload-team" :aria-label="t('组员工作量统计')">
      <header class="workload-team-heading"><div><span class="workload-eyebrow">{{t('研发组长视图')}}</span><h2>{{t('组员工作量统计')}}</h2><p>{{t('仅展示当前主部门中、且已加入本人具有研发组长角色项目的活跃组员。')}}</p></div><span class="workload-team-count">{{t('{count} 位组员',{count:personalReport.team.memberCount||0})}}</span></header>
      <p class="workload-team-scope">{{personalReport.team.departmentName}} · {{t('{count} 个组长负责项目',{count:personalReport.team.projectCount||0})}} · {{t('按当前组织与项目成员关系实时计算')}}</p>
      <p v-if="teamError" class="workload-error" role="alert">{{t(teamError)}}</p>
      <div v-else-if="teamLoading" class="workload-team-loading" role="status"><span class="spinner"></span>{{t('正在计算组员工作量…')}}</div>
      <ScrollArea v-else-if="teamReport" class="workload-team-table-scroll" horizontal><table class="workload-table workload-team-table"><thead><tr><th>{{t('成员')}}</th><th>{{t('已填工作权重')}}</th><th>{{t('关联需求')}}</th><th>{{t('已上线需求')}}</th><th>{{t('迭代缺陷')}}</th><th>{{t('未估算职能项')}}</th></tr></thead><tbody><tr v-for="person in teamReport.people" :key="person.userId"><td><div class="workload-person"><span class="workload-avatar">{{person.name.slice(0,1)}}</span><b>{{person.name}}</b></div></td><td class="workload-weight">{{formatWeight(person.weight)}}</td><td>{{formatNumber(person.requirementCount)}}</td><td><span class="workload-shipped">{{formatNumber(person.shippedRequirementCount)}}</span></td><td>{{formatNumber(person.defectCount)}}</td><td><span :class="{'workload-missing':person.unestimatedRoleCount>0}">{{formatNumber(person.unestimatedRoleCount)}}</span></td></tr></tbody></table></ScrollArea>
    </section>
    <p v-if="error" class="workload-error" role="alert">{{t(error)}}</p>
    <div v-if="forbidden&&!report" class="workload-company-note"><Icon name="lock" :size="16"/><span>{{t('企业工作量统计暂不可用，请联系企业管理员确认团队统计权限。')}}</span></div>
    <div v-else-if="!workspace.canViewReports" class="workload-company-note"><Icon name="lock" :size="16"/><span>{{t('个人工作量已显示在上方；企业范围统计需要企业管理员或团队统计权限。')}}</span></div>
    <template v-if="report">
      <section class="workload-company"><header class="workload-company-heading"><div><span class="workload-eyebrow">{{t('企业视图')}}</span><h2>{{t('企业工作量统计')}}</h2></div><span>{{t('已获团队统计授权')}}</span></header><div class="workload-scope"><span><i></i>{{report.scope.tenantName}} · {{t('全公司范围')}} · {{t('{count} 个项目',{count:report.scope.projectCount})}} · {{t('{count} 个迭代',{count:report.sprintCount})}}</span><small>{{t('当前状态快照')}} · {{formatDate(report.generatedAt)}}</small></div>
      <section class="workload-cards"><article v-for="metric in metrics" :key="metric.key"><span>{{t(metric.name)}}</span><b>{{metric.key==='weight'?formatWeight(report.totals.weight):formatNumber(report.totals[metric.key])}}</b><small>{{t(metric.key==='weight'?'职能权重相加，不是工时':metric.key==='shippedRequirementCount'?'已完成类别且属于工作流结束状态':'公司范围按工作项 ID 去重')}}</small></article></section>
      <section v-if="hasGaps" class="workload-gaps" role="status"><strong>{{t('数据完整性提示')}}</strong><span v-if="report.unestimatedRequirementCount">{{t('{count} 条需求尚未填入任何权重',{count:report.unestimatedRequirementCount})}}</span><span v-if="report.unassignedWeight">{{t('未分配权重：{value}',{value:formatWeight(report.unassignedWeight)})}}</span><span v-if="report.unassignedRequirementCount">{{t('{count} 条需求未绑定职能成员',{count:report.unassignedRequirementCount})}}</span><span v-if="report.unassignedDefectCount">{{t('{count} 个缺陷缺少稳定处理人 ID',{count:report.unassignedDefectCount})}}</span><span v-if="report.ambiguousSprintItemCount">{{t('{count} 个历史工作项的迭代简称有歧义，未计入',{count:report.ambiguousSprintItemCount})}}</span></section>
      <WorkloadTrends :month="month" :refresh-key="trendRefresh" :disabled="identityConflict||!monthValid"/>
      <section class="workload-detail"><div class="workload-toolbar"><div class="workload-tabs" role="tablist" :aria-label="t('统计维度')"><button v-for="item in dimensions" :key="item.key" type="button" role="tab" :aria-selected="dimension===item.key" :class="{active:dimension===item.key}" @click="dimension=item.key">{{t(item.name)}}<small>{{item.key==='people'?report.people.length:item.key==='departments'?report.departments.length:report.roles.length}}</small></button></div><div class="workload-filters"><input v-model="search" :aria-label="t('搜索统计明细')" :placeholder="t('搜索姓名、部门或职能')"/><AppSelect v-if="dimension==='people'" class="workload-filter-select" :model-value="department" :options="departmentOptions" :label="t('筛选所属部门')" @update:model-value="selectDepartment"/><AppSelect v-if="dimension==='people'" class="workload-filter-select" :model-value="role" :options="roleOptions" :label="t('筛选职能')" @update:model-value="selectRole"/></div></div>
        <ScrollArea class="workload-table-scroll" horizontal><table class="workload-table"><thead><tr><th class="workload-rank">{{t('序号')}}</th><th :aria-sort="sort==='name'?(descending?'descending':'ascending'):'none'"><button type="button" @click="changeSort('name')">{{t(dimension==='people'?'成员':dimension==='departments'?'部门':'职能')}} <span>{{sort==='name'?(descending?'↓':'↑'):'↕'}}</span></button></th><th v-if="dimension==='people'">{{t('所属部门 / 职能')}}</th><th v-if="dimension==='departments'">{{t('参与成员')}}</th><th v-for="metric in metrics" :key="metric.key" :aria-sort="sort===metric.key?(descending?'descending':'ascending'):'none'"><button type="button" @click="changeSort(metric.key)">{{t(metric.name)}} <span>{{sort===metric.key?(descending?'↓':'↑'):'↕'}}</span></button></th><th>{{t('未估算职能项')}}</th></tr></thead><tbody><tr v-for="(row,index) in rows" :key="row.id"><td class="workload-rank">{{index+1}}</td><td><div class="workload-person"><span class="workload-avatar" :class="{inactive:row.active===false}">{{row.name.slice(0,1)}}</span><div><b>{{row.name}}</b><small v-if="row.active===false">{{t('历史停用成员')}}</small></div></div></td><td v-if="dimension==='people'"><div class="workload-person-meta"><span>{{row.departmentName||t('未分配部门')}}</span><small>{{(row.roleKeys||[]).map(key=>t(workloadRoleNames[key]||key)).join(' · ')}}</small></div></td><td v-if="dimension==='departments'">{{row.memberCount}}</td><td class="workload-weight">{{formatWeight(row.weight)}}<small v-if="row.unestimatedRoleCount&&row.estimatedRoleCount===0">{{t('尚未估算')}}</small></td><td>{{formatNumber(row.requirementCount)}}</td><td><span class="workload-shipped">{{formatNumber(row.shippedRequirementCount)}}</span></td><td>{{formatNumber(row.defectCount)}}</td><td><span :class="{'workload-missing':row.unestimatedRoleCount>0}">{{formatNumber(row.unestimatedRoleCount)}}</span></td></tr></tbody></table><div v-if="!rows.length" class="workload-empty"><h2>{{t('暂无匹配的统计记录')}}</h2><p>{{t('仅显示本月迭代需求职能或缺陷的实际参与者，不生成虚假的零工作量成员。')}}</p><Button v-if="search||department!=='*'||role" variant="outline" @click="resetFilters">{{t('清除筛选')}}</Button></div></ScrollArea>
        <footer class="workload-detail-footer"><span>{{t('{count} 条明细',{count:rows.length})}}</span><span>{{t('筛选仅影响明细；顶部总览始终为公司全量。')}}<template v-if="dimension==='people'&&role"> {{t('已按所选职能展示个人指标。')}}</template></span></footer>
      </section>
      <details class="workload-definitions"><summary>{{t('统计口径与使用说明')}}</summary><ul><li>{{t('月份采用 UTC 日历日期的迭代结束日；待规划、无结束日期及其他月份迭代不计入。')}}</li><li>{{t('每条需求的前端、后端、算法、UI、产品权重独立计入；同职能绑定多人时等分该项权重，汇总后保留六位小数。')}}</li><li>{{t('个人需求与上线数按五职能绑定成员归属。部门按当前有效主部门归属，无主部门时取排序首个有效关系；无关系单列。')}}</li><li>{{t('已上线包含 category=done 且配置为工作流结束状态的需求；统计使用当前状态，不代表该月实际发布事件。')}}</li><li>{{t('缺陷按自身迭代归月、稳定处理人 ID 归人、缺陷职能归类；不按姓名推断处理人，不代表个人缺陷责任。')}}</li><li>{{t('公司、部门和职能数量分别按工作项 ID 去重；一条需求可涉及多个部门或职能，因此分组数量不能直接相加。')}}</li><li>{{t('这是当前数据与组织关系的快照。仅用于协作计划，不应单独作为绩效或薪酬依据。')}}</li></ul></details>
      </section>
    </template>
  </div>
</template>

